+import { test } from 'node:test'
+import assert from 'node:assert/strict'
+import os from 'node:os'
+import path from 'node:path'
+import fs from 'node:fs'
+import { JsonStore } from '../src/store.js'
+
+test('JsonStore load/save roundtrip and missing file', async () => {
+  const tmp = path.join(os.tmpdir(), `bookstore-test-${Date.now()}.json`)
+  try {
+    const store = new JsonStore(tmp)
+    const miss = await store.load()
+    assert.equal(miss, null)
+    const data = [{ id: 'x', title: 'X', author: 'A', priceCents: 100, stock: 1 }]
+    await store.save(data)
+    const loaded = await store.load()
+    assert.deepEqual(loaded, data)
+  } finally {
+    try { fs.unlinkSync(tmp) } catch {}
+  }
+})
+
